                    return{
                        ...errorObj,
                        [key]: null
                    }
                })
            }
        },
        email: (key,val)=>{
            if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)){
                setErrorObj((errorObj)=>{
                    return{
                        ...errorObj,
                        [key]: 'you cannot have numbers in it '
                    }
                })
                console.log(errorObj);
            }else{
                setErrorObj((errorObj)=>{
                    return{
                        ...errorObj,
                        [key]: null
                    }
                })
            }
        },
        mobile: (key,val)=>{
            if(!/^\d{10}$/.test(val)){
                setErrorObj((errorObj)=>{
                    return{
                        ...errorObj,
                        [key]: 'you cannot have alphabets in it '
                    }
                })
                console.log(errorObj);
            }else{
                setErrorObj((errorObj)=>{
                    return{
                        ...errorObj,
                        [key]: null
                    }
                })
            }
        }
    }

