            setFormData({    // to clean up the input field after submission
                name:'',
                email: "",
                mobile:""
            })
        }} >
            <h2>Fill The Details</h2>

            <div className="field-container" >
            <label>Name: </label>
            <input type="text" placeholder="type your Name"
